class AnswerGenerator(BaseComponent):
    def __init__(self, config: ComponentConfig):
        self.config = config

    def forward(self, *, rewritten_query: str, hints: str, **_) -> dict:
        # If hints are empty or insufficient, return default no info answer
        if not hints.strip() or hints.strip().lower() in ("no hints", "no relevant hints", "no hints found"):
            return {"answer": "No sufficient information found to answer the query."}

        prompt = (
            f"{self.config.prompt_template}\n\n"
            f"Query: {rewritten_query}\n\n"
            f"Hints:\n{hints}\n\n"
            f"Answer:"
        )
        resp = llm_call(
            prompt,
            model=self.config.model,
            max_tokens=self.config.max_tokens,
            temperature=self.config.temperature,
        )
        return {"answer": resp.text}

